{"content":"# -*- coding: utf-8 -*-
import os, re, urllib.parse, sys

ROOT = r'c:\calculadoras-de-enfermagem'

EXCLUDED_DIRS = {
    'node_modules', '.git', 'downloads', 'biblioteca', 'blog', 'blog-templates',
    'backups-temporarios', 'automacoes', 'scripts', '.github', 'supabase',
    'CATALOGO_DOS_AGENTES_E_HOOKS', 'CATALOGO_DA_ARQUITETURA_ESTRUTURAL',
    'CATALOGO_DE_ESTRUTURA_FISICA', 'CATALOGO_DE_IDENTIDADE_VISUAL',
    'CATALOGO_SEO_METAS_HEAD', 'CATALOGO_INTRUCOES_CRIACAO_DE_FORMULARIOS',
    'SISTEMA_DE_LOGIN_DO_SITE', 'governance', 'knowledge', 'AI_ORCHESTRATION',
    'js', 'public', 'src', 'docs', 'img', 'fonts',
}
EXCLUDED_FILES = {
    'footer.html', 'menu-global.html', 'global-body-elements.html',
    'downloads.html', '_language_selector.html', 'googlefc0a17cdd552164b.html',
}

# Índice de todos os arquivos existentes (caminho relativo com /, normalizado)
existing = set()
for dp, dns, fns in os.walk(ROOT):
    rel_dp = os.path.relpath(dp, ROOT)
    parts = rel_dp.split(os.sep)
    if parts[0] in EXCLUDED_DIRS:
        dns[:] = []
        continue
    for fn in fns:
        rp = os.path.relpath(os.path.join(dp, fn), ROOT).replace('\\', '/')
        existing.add(rp)
        # também sem extensão? não; mantemos exato.

def norm_url(u):
    # remove fragment e query
    u = u.split('#', 1)[0].split('?', 1)[0]
    u = urllib.parse.unquote(u)
    return u

ATTR = re.compile(r'\b(href|src)\s*=\s*["\']([^"\']+)["\']', re.I)

doubles = []   # (arquivo, url)
htm_trunc = [] # (arquivo, url)
spaces = []    # (arquivo, url)
broken = []    # (arquivo, url, destino_resolvido)

def resolve(url, file_dir):
    if url.startswith('/'):
        p = url.lstrip('/')
    else:
        p = os.path.normpath(os.path.join(file_dir, url)).replace('\\', '/')
    return p

html_files = []
for dp, dns, fns in os.walk(ROOT):
    rel_dp = os.path.relpath(dp, ROOT)
    parts = rel_dp.split(os.sep)
    if parts[0] in EXCLUDED_DIRS:
        dns[:] = []
        continue
    for fn in fns:
        if fn.lower().endswith('.html') and fn not in EXCLUDED_FILES:
            html_files.append(os.path.join(dp, fn))

print('Arquivos HTML varridos:', len(html_files))

for fp in html_files:
    rel = os.path.relpath(fp, ROOT).replace('\\', '/')
    file_dir = os.path.dirname(rel).replace('\\', '/')
    with open(fp, encoding='utf-8', errors='replace') as f:
        content = f.read()
    for attr, url in ATTR.findall(content):
        if not url:
            continue
        low = url.lower()
        if low.startswith(('http://', 'https://', '//', 'mailto:', 'tel:', 'javascript:', 'data:', '#')):
            continue
        # barra dupla no meio do path
        # ex: /sv//x.html  ou  sv//x.html
        m = re.search(r'[^:/]//', url)
        if m and '://' not in url:
            doubles.append((rel, url))
        n = norm_url(url)
        if n.lower().endswith('.htm') and not n.lower().endswith('.html'):
            htm_trunc.append((rel, url))
        if ' ' in n:
            spaces.append((rel, url))
        dest = resolve(n, file_dir)
        if not dest:
            continue
        # ignora âncoras vazias e links para diretório
        if dest.endswith('/'):
            continue
        if dest not in existing:
            broken.append((rel, url, dest))

def uniq(lst):
    seen = set(); out = []
    for item in lst:
        k = (item[0], item[1])
        if k in seen: continue
        seen.add(k); out.append(item)
    return out

doubles = uniq(doubles); htm_trunc = uniq(htm_trunc); spaces = uniq(spaces); broken = uniq(broken)

