{"content":"import os, re, io

ROOT = r'c:\calculadoras-de-enfermagem'
EXCLUDE_DIRS = {'node_modules', '.git', 'downloads', 'biblioteca', 'blog', 'blog-templates',
                'backups-temporarios', 'automacoes', 'backups_seo', 'backup'}
EXCLUDE_FILES = {'footer.html', 'menu-global.html', 'global-body-elements.html',
                 'downloads.html', '_language_selector.html', 'googlefc0a17cdd552164b.html'}

total_i18n = 0
empty_i18n = []
empty_lang = []
files_scanned = 0

for dp, dns, fns in os.walk(ROOT):
    top = os.path.relpath(dp, ROOT).split(os.sep)[0]
    if top in EXCLUDE_DIRS:
        dns[:] = []
        continue
    for fn in fns:
        if not fn.lower().endswith('.html') or fn in EXCLUDE_FILES:
            continue
        rel = os.path.relpath(os.path.join(dp, fn), ROOT).replace('\\', '/')
        c = io.open(os.path.join(dp, fn), encoding='utf-8', errors='replace').read()
        files_scanned += 1
        keys = re.findall(r'data-i18n(?:-aria-label)?="([^"]*)"', c)
        total_i18n += len(keys)
        for k in keys:
            if k.strip() == '':
                empty_i18n.append(rel)
        m = re.search(r'<html\s+lang="([^"]*)"', c)
        if m and m.group(1).strip() == '':
            empty_lang.append(rel)

print('Arquivos HTML varridos:', files_scanned)
print('Total de chaves data-i18n:', total_i18n)
print('data-i18n VAZIOS:', len(empty_i18n))
for r in empty_i18n[:20]:
    print('   ', r)
print('html lang VAZIOS:', len(empty_lang))
for r in empty_lang[:20]:
    print('   ', r)
print('RESULTADO:', 'INTEGRO (nenhuma chave de traducao vazia)' if not empty_i18n and not empty_lang else 'PROBLEMA')
