{"code":"return await page.evaluate(() => {
  const hero = document.querySelector('main .hero, main > header.hero');
  if (!hero) return { error: 'no hero' };
  const out = [];
  const sheets = Array.from(document.styleSheets);
  for (const sheet of sheets) {
    let rules;
    try { rules = sheet.cssRules; } catch (e) { continue; }
    if (!rules) continue;
    for (const rule of rules) {
      try {
        const sel = rule.selectorText;
        if (!sel) continue;
        // verifica se a regra casa com o hero e define z-index
        let matches = false;
        try { matches = hero.matches(sel.split(',').map(s=>s.trim()).join(',')); } catch(e){ continue; }
        if (!matches) continue;
        const style = rule.style;
        if (style.zIndex) {
          out.push({ sel: sel.slice(0,80), zIndex: style.zIndex, important: style.getPropertyPriority('z-index') });
        }
      } catch(e) {}
    }
  }
  // também verifica regras que aplicam z-index a 'header' genericamente
  const headerRules = [];
  for (const sheet of sheets) {
    let rules;
    try { rules = sheet.cssRules; } catch (e) { continue; }
    if (!rules) continue;
    for (const rule of rules) {
      try {
        const sel = (rule.selectorText||'');
        if (/^header\b|header\{|^header[,.]/i.test(sel.trim()) && rule.style && rule.style.zIndex) {
          headerRules.push({ sel: sel.slice(0,80), zIndex: rule.style.zIndex });
        }
      } catch(e){}
    }
  }
  return { zRulesOnHero: out, headerZRules: headerRules };
});","pageId":"9bae6129-a638-453b-82a7-7df625c37a79"}

