{"filePath":"c:\calculadoras-de-enfermagem\backups-temporarios\_remove_mini_calc.js","content":"const fs = require('fs');
const path = require('path');

const root = 'C:\\calculadoras-de-enfermagem';
const langs = ['ar','de','en','es','fr','hi','id','it','ja','ko','nl','pl','ru','sv','tr','uk','vi','zh'];
const files = ['index.html'].concat(langs.map(l => l + '/index.html'));

const MARK_RAIZ = '<!-- ===================== MINI CALCULADORAS ===================== -->';
const MARK_LANG = '<!-- INÍCIO: FAIXA DE MINI CALCULADORAS GLASSMORPHISM -->';
const MARK_FIM  = '<!-- FIM: FAIXA DE MINI CALCULADORAS -->';

const stamp = new Date().toISOString().replace(/[:.]/g, '-');
const backupDir = path.join(root, 'backups-temporarios', 'mini-calc-removal-' + stamp);
fs.mkdirSync(backupDir, { recursive: true });

const report = [];
for (const f of files) {
  const p = path.join(root, f);
  const raw = fs.readFileSync(p, 'utf8');

  let start = raw.indexOf(MARK_LANG);
  if (start < 0) start = raw.indexOf(MARK_RAIZ);
  if (start < 0) { report.push({ file: f, status: 'SKIP: início não encontrado' }); continue; }

  const fimIdx = raw.indexOf(MARK_FIM, start);
  if (fimIdx < 0) { report.push({ file: f, status: 'SKIP: FIM não encontrado' }); continue; }

  const scriptStart = raw.indexOf('<script>', fimIdx);
  if (scriptStart < 0) { report.push({ file: f, status: 'SKIP: <script> não encontrado' }); continue; }

  const scriptEnd = raw.indexOf('</script>', scriptStart);
  if (scriptEnd < 0) { report.push({ file: f, status: 'SKIP: </script> não encontrado' }); continue; }

  const scriptBlock = raw.slice(scriptStart, scriptEnd);
  if (!scriptBlock.includes('btnMiniGaso')) { report.push({ file: f, status: 'SKIP: script não é das mini calculadoras' }); continue; }

  const endPos = scriptEnd + '</script>'.length;

  // backup do original (preserva a estrutura de pastas)
  const backupPath = path.join(backupDir, f);
  fs.mkdirSync(path.dirname(backupPath), { recursive: true });
  fs.writeFileSync(backupPath, raw, 'utf8');

  let out = raw.slice(0, start) + raw.slice(endPos);
  out = out.replace(/\n{3,}/g, '\n\n');
  fs.writeFileSync(p, out, 'utf8');

  report.push({ file: f, status: 'OK', removedChars: endPos - start });
}

console.log(JSON.stringify(report, null, 2));
"}

