{"content":"const fs = require('fs');
const path = require('path');

const root = 'C:\\calculadoras-de-enfermagem';
const langs = ['ar','de','en','es','fr','hi','id','it','ja','ko','nl','pl','ru','sv','tr','uk','vi','zh'];
const files = ['index.html'].concat(langs.map(l => l + '/index.html'));

const FROM = 'index-hero-cards lg:col-span-4 space-y-2';
const TO   = 'index-hero-cards lg:col-span-4 grid auto-rows-fr gap-2';

const stamp = new Date().toISOString().replace(/[:.]/g, '-');
const backupDir = path.join(root, 'backups-temporarios', 'side-card-equal-height-' + stamp);
fs.mkdirSync(backupDir, { recursive: true });

const report = [];
for (const f of files) {
  const p = path.join(root, f);
  const raw = fs.readFileSync(p, 'utf8');
  const count = raw.split(FROM).length - 1;
  if (count !== 1) { report.push({ file: f, status: 'SKIP (ocorrências != 1)', count }); continue; }

  const backupPath = path.join(backupDir, f);
  fs.mkdirSync(path.dirname(backupPath), { recursive: true });
  fs.writeFileSync(backupPath, raw, 'utf8');

  const out = raw.replace(FROM, TO);
  fs.writeFileSync(p, out, 'utf8');
  report.push({ file: f, status: 'OK' });
}
console.log(JSON.stringify(report, null, 2));
